import React, { useState, useEffect, useRef, useMemo } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { MediaAsset } from '../types';

interface LivePhotoCardProps {
  coverAsset: MediaAsset;
  gallery: MediaAsset[];
  title: string;
  staggerIndex?: number;
  intervalMs?: number;
  onOpenLightbox: (activeAsset: MediaAsset, allAssets: MediaAsset[]) => void;
  className?: string;
}

function getOrientationCategory(aspectRatio?: string): 'vertical' | 'horizontal' | 'square' {
  if (!aspectRatio) return 'horizontal';
  if (aspectRatio === '1:1') return 'square';
  const parts = aspectRatio.split(':').map(Number);
  if (parts.length === 2 && parts[0] > 0 && parts[1] > 0) {
    if (parts[0] < parts[1]) return 'vertical';
    if (parts[0] > parts[1]) return 'horizontal';
    return 'square';
  }
  return 'horizontal';
}

function getExplicitDimensions(aspectRatio?: string): { width: number; height: number } {
  const parts = aspectRatio?.split(':').map(Number);
  if (parts && parts.length === 2 && parts[0] > 0 && parts[1] > 0) {
    return parts[0] >= parts[1]
      ? { width: 1200, height: Math.round((1200 * parts[1]) / parts[0]) }
      : { width: Math.round((1200 * parts[0]) / parts[1]), height: 1200 };
  }
  return { width: 1200, height: 800 };
}

export const LivePhotoCard: React.FC<LivePhotoCardProps> = ({
  coverAsset,
  gallery,
  title,
  staggerIndex = 0,
  intervalMs = 3600,
  onOpenLightbox,
  className = '',
}) => {
  const allAssets = useMemo(() => {
    const list = [coverAsset, ...gallery];
    const seen = new Set<string>();
    return list.filter((item) => {
      if (!item?.url || seen.has(item.url)) return false;
      seen.add(item.url);
      return true;
    });
  }, [coverAsset, gallery]);

  const slideAssets = useMemo(() => {
    if (allAssets.length <= 1) return allAssets;
    const coverOrientation = getOrientationCategory(coverAsset.aspectRatio);
    const sameOrientation = allAssets.filter(
      (a) => getOrientationCategory(a.aspectRatio) === coverOrientation
    );
    return sameOrientation.length >= 2 ? sameOrientation : allAssets;
  }, [allAssets, coverAsset]);

  const [activeIndex, setActiveIndex] = useState<number>(0);
  const [loadedUrls, setLoadedUrls] = useState<Record<string, boolean>>({});
  const [isHovered, setIsHovered] = useState<boolean>(false);
  const [isInView, setIsInView] = useState<boolean>(false);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState<boolean>(false);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const touchStartXRef = useRef<number | null>(null);

  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          setIsInView(entry.isIntersecting);
        });
      },
      { rootMargin: '250px 0px', threshold: 0.05 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (prefersReducedMotion || !isInView || slideAssets.length <= 1) return;
    const nextIdx = (activeIndex + 1) % slideAssets.length;
    const nextAsset = slideAssets[nextIdx];
    if (nextAsset?.url && !loadedUrls[nextAsset.url]) {
      const img = new Image();
      img.onload = () => {
        setLoadedUrls((prev) => ({ ...prev, [nextAsset.url]: true }));
      };
      img.src = nextAsset.url;
    }
  }, [activeIndex, isInView, slideAssets, prefersReducedMotion, loadedUrls]);

  useEffect(() => {
    if (prefersReducedMotion || !isInView || isHovered || slideAssets.length <= 1) return;

    const effectiveInterval = intervalMs + (staggerIndex % 4) * 200;
    const timer = window.setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % slideAssets.length);
    }, effectiveInterval);

    return () => window.clearInterval(timer);
  }, [prefersReducedMotion, isInView, isHovered, slideAssets.length, intervalMs, staggerIndex]);

  const currentAsset = slideAssets[activeIndex] || coverAsset;
  const isCurrentSlideLoaded = activeIndex === 0 || Boolean(loadedUrls[currentAsset.url]);
  const coverDims = getExplicitDimensions(coverAsset.aspectRatio);

  const handlePrev = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveIndex((prev) => (prev - 1 + slideAssets.length) % slideAssets.length);
  };

  const handleNext = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveIndex((prev) => (prev + 1) % slideAssets.length);
  };

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartXRef.current = e.touches[0]?.clientX ?? null;
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (touchStartXRef.current === null || slideAssets.length <= 1) return;
    const endX = e.changedTouches[0]?.clientX ?? touchStartXRef.current;
    const diff = endX - touchStartXRef.current;
    touchStartXRef.current = null;
    if (Math.abs(diff) > 40) {
      if (diff < 0) {
        setActiveIndex((prev) => (prev + 1) % slideAssets.length);
      } else {
        setActiveIndex((prev) => (prev - 1 + slideAssets.length) % slideAssets.length);
      }
    }
  };

  return (
    <div
      ref={containerRef}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onClick={() => onOpenLightbox(currentAsset, allAssets)}
      className={`relative overflow-hidden rounded-2xl cursor-pointer group/card bg-[#0d0f14] ${className}`}
      data-protected-media="true"
    >
      <img
        src={coverAsset.url}
        alt={`${title || coverAsset.titleEn} – photo by Dino / Dino Studio`}
        width={coverDims.width}
        height={coverDims.height}
        decoding="async"
        draggable={false}
        onContextMenu={(e) => e.preventDefault()}
        loading="lazy"
        className={`w-full h-auto block rounded-2xl transition-transform duration-700 group-hover/card:scale-[1.02] select-none ${
          activeIndex === 0 || !isCurrentSlideLoaded ? 'opacity-100' : 'opacity-0'
        }`}
      />

      {slideAssets.length > 1 && activeIndex > 0 && (
        <img
          key={currentAsset.id || currentAsset.url}
          src={currentAsset.url}
          alt={`${title || currentAsset.titleEn} – photo by Dino / Dino Studio`}
          width={coverDims.width}
          height={coverDims.height}
          decoding="async"
          draggable={false}
          onContextMenu={(e) => e.preventDefault()}
          onLoad={() =>
            setLoadedUrls((prev) => ({ ...prev, [currentAsset.url]: true }))
          }
          className={`absolute inset-0 w-full h-full object-contain bg-[#07080a] block rounded-2xl transition-opacity duration-300 group-hover/card:scale-[1.02] select-none ${
            isCurrentSlideLoaded ? 'opacity-100' : 'opacity-0'
          }`}
        />
      )}

      {slideAssets.length > 1 && (
        <>
          <button
            type="button"
            onClick={handlePrev}
            aria-label={`Previous photo in ${title}`}
            className="absolute left-2.5 sm:left-3 top-1/2 -translate-y-1/2 w-8 h-8 sm:w-9 sm:h-9 rounded-full bg-black/60 hover:bg-white text-white hover:text-black backdrop-blur-md flex items-center justify-center opacity-80 sm:opacity-0 sm:group-hover/card:opacity-100 transition-all duration-200 cursor-pointer z-10 shadow-lg"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>

          <button
            type="button"
            onClick={handleNext}
            aria-label={`Next photo in ${title}`}
            className="absolute right-2.5 sm:right-3 top-1/2 -translate-y-1/2 w-8 h-8 sm:w-9 sm:h-9 rounded-full bg-black/60 hover:bg-white text-white hover:text-black backdrop-blur-md flex items-center justify-center opacity-80 sm:opacity-0 sm:group-hover/card:opacity-100 transition-all duration-200 cursor-pointer z-10 shadow-lg"
          >
            <ChevronRight className="w-4 h-4" />
          </button>

          <div className="absolute bottom-3 right-3 px-2.5 py-1 rounded-full bg-black/65 backdrop-blur-md text-[10px] font-mono text-white/90 pointer-events-none select-none z-10">
            {String(activeIndex + 1).padStart(2, '0')} / {String(slideAssets.length).padStart(2, '0')}
          </div>
        </>
      )}
    </div>
  );
};
