import React, { useState, useEffect, useCallback } from 'react';
import { Navbar, ChapterFilter } from './components/Navbar';
import { Footer } from './components/Footer';
import { LightboxModal } from './components/LightboxModal';
import { VideoPlayerModal } from './components/VideoPlayerModal';
import { HomeView } from './views/HomeView';
const PortfolioView = React.lazy(() => import('./views/PortfolioView').then((m) => ({ default: m.PortfolioView })));
const ProjectDetailView = React.lazy(() => import('./views/ProjectDetailView').then((m) => ({ default: m.ProjectDetailView })));
const ServicesView = React.lazy(() => import('./views/ServicesView').then((m) => ({ default: m.ServicesView })));
const AboutView = React.lazy(() => import('./views/AboutView').then((m) => ({ default: m.AboutView })));
const ContactView = React.lazy(() => import('./views/ContactView').then((m) => ({ default: m.ContactView })));
const PrivacyView = React.lazy(() => import('./views/PrivacyView').then((m) => ({ default: m.PrivacyView })));
import { Language, MediaAsset, PortfolioProject } from './types';
import { PORTFOLIO_PROJECTS } from './data/portfolioData';
import { ASSET_BASE_URL, HIDDEN_PORTFOLIO_IDS, SITE_URL } from './config';
import { getProjectDescription, getProjectTitle, getPageMetadata } from './utils/seoMetadata';

const VALID_VIEWS = ['home', 'work', 'services', 'about', 'contact', 'privacy'] as const;

const SWEDISH_ROUTE_ALIASES: Record<string, string> = {
  arbeten: 'work',
  tjanster: 'services',
  'om-studion': 'about',
  'digitala-losningar': 'services',
  kontakt: 'contact',
};

export function parsePathAndHash(
  pathname: string,
  hash = ''
): { view: string; projectId?: string; language: Language } {
  const cleanHash = hash.replace(/^#\/?/, '').trim();
  const routeHash =
    (VALID_VIEWS as readonly string[]).includes(cleanHash) || cleanHash.startsWith('project/')
      ? cleanHash
      : '';
  const cleanPath = pathname.replace(/^\/+|\/+$/g, '').trim();
  const parts = cleanPath ? cleanPath.split('/') : [];
  let language: Language = 'sv';

  if (parts[0] === 'sv' || parts[0] === 'en') {
    language = parts[0];
    parts.shift();
  }

  let rawRoute = routeHash || parts.join('/');

  if (rawRoute in SWEDISH_ROUTE_ALIASES) {
    if (parts[0] !== 'en') language = 'sv';
    rawRoute = SWEDISH_ROUTE_ALIASES[rawRoute];
  }

  if (!rawRoute || rawRoute === 'home') {
    return { view: 'home', language };
  }

  if (rawRoute.startsWith('project/')) {
    const pId = decodeURIComponent(rawRoute.replace('project/', ''));
    if (HIDDEN_PORTFOLIO_IDS.has(pId)) {
      return { view: 'work', language };
    }
    const match = PORTFOLIO_PROJECTS.find(
      (p) => !HIDDEN_PORTFOLIO_IDS.has(p.id) && (p.id === pId || p.slug === pId)
    );
    return match ? { view: 'project', projectId: match.id, language } : { view: 'work', language };
  }

  if ((VALID_VIEWS as readonly string[]).includes(rawRoute)) {
    return { view: rawRoute, language };
  }

  return { view: 'home', language };
}

function parseLocationToRoute(): { view: string; projectId?: string; language: Language; chapter: ChapterFilter } {
  if (typeof window === 'undefined') {
    return { view: 'home', language: 'sv', chapter: 'all' };
  }
  const route = parsePathAndHash(window.location.pathname, window.location.hash);
  const searchParams = new URLSearchParams(window.location.search);
  const chapterParam = searchParams.get('chapter') as ChapterFilter | null;
  if (chapterParam && ['sports', 'editorial', 'film', 'digital'].includes(chapterParam)) {
    return { ...route, chapter: chapterParam };
  }
  return { ...route, chapter: 'all' };
}

// Verified SEO descriptions (tested in portfolioData.test.ts):
// About EN: 'Dino Studio is run by Dino — photographer, filmmaker and photojournalist in Stockholm working across event photography, film and photojournalism.'
function updatePageMetadata(view: string, language: Language, projectId?: string) {
  if (typeof document === 'undefined') return;

  const isSv = language === 'sv';
  document.documentElement.lang = isSv ? 'sv' : 'en';

  const proj = projectId ? PORTFOLIO_PROJECTS.find((p) => p.id === projectId || p.slug === projectId) : undefined;
  const meta = getPageMetadata(view, language, proj);

  document.title = meta.title;

  const setMeta = (selector: string, content: string) => {
    const el = document.querySelector(selector);
    if (el) el.setAttribute('content', content);
  };

  setMeta('meta[name="description"]', meta.description);
  setMeta('meta[property="og:title"]', meta.title);
  setMeta('meta[property="og:description"]', meta.description);
  setMeta('meta[property="og:url"]', `${SITE_URL}${meta.canonicalPath}`);
  setMeta('meta[property="og:image"]', meta.ogImage);
  setMeta('meta[name="twitter:title"]', meta.title);
  setMeta('meta[name="twitter:description"]', meta.description);
  setMeta('meta[name="twitter:image"]', meta.ogImage);

  const canonicalLink = document.querySelector('link[rel="canonical"]');
  if (canonicalLink) {
    canonicalLink.setAttribute('href', `${SITE_URL}${meta.canonicalPath}`);
  }

  const pureSubPath = meta.canonicalPath.replace(/^\/(sv|en)/, '');
  const hreflangSv = document.querySelector('link[rel="alternate"][hreflang="sv"]');
  if (hreflangSv) {
    hreflangSv.setAttribute('href', `${SITE_URL}/sv${pureSubPath}`);
  }
  const hreflangEn = document.querySelector('link[rel="alternate"][hreflang="en"]');
  if (hreflangEn) {
    hreflangEn.setAttribute('href', `${SITE_URL}/en${pureSubPath}`);
  }
  const hreflangDefault = document.querySelector('link[rel="alternate"][hreflang="x-default"]');
  if (hreflangDefault) {
    hreflangDefault.setAttribute('href', `${SITE_URL}/sv${pureSubPath}`);
  }
}

export default function App({ initialPath }: { initialPath?: string } = {}) {
  const initialRoute = initialPath ? parsePathAndHash(initialPath) : parseLocationToRoute();
  const [currentView, setCurrentView] = useState<string>(initialRoute.view);
  const [currentProjectId, setCurrentProjectId] = useState<string>(
    initialRoute.projectId || 'we-are-family-nile-rodgers'
  );
  const [activeChapter, setActiveChapter] = useState<ChapterFilter>(
    (initialRoute as { chapter?: ChapterFilter }).chapter || 'all'
  );
  const [language, setLanguage] = useState<Language>(initialRoute.language);

  // Lightbox state
  const [lightboxAsset, setLightboxAsset] = useState<MediaAsset | null>(null);
  const [lightboxGallery, setLightboxGallery] = useState<MediaAsset[]>([]);
  const [isLightboxOpen, setIsLightboxOpen] = useState<boolean>(false);

  // Video screening modal state
  const [videoProject, setVideoProject] = useState<PortfolioProject | null>(null);
  const [isVideoModalOpen, setIsVideoModalOpen] = useState<boolean>(false);

  // Synchronize clean URLs (popstate) and hash changes
  useEffect(() => {
    const syncRoute = () => {
      const parsed = parseLocationToRoute();
      setCurrentView(parsed.view);
      setLanguage(parsed.language);
      setIsLightboxOpen(false);
      setIsVideoModalOpen(false);
      if (parsed.projectId) {
        setCurrentProjectId(parsed.projectId);
      }
      setActiveChapter(parsed.chapter);
    };

    window.addEventListener('popstate', syncRoute);
    window.addEventListener('hashchange', syncRoute);
    return () => {
      window.removeEventListener('popstate', syncRoute);
      window.removeEventListener('hashchange', syncRoute);
    };
  }, []);

  // Update page title, meta description, and Open Graph tags on route or language change
  useEffect(() => {
    updatePageMetadata(currentView, language, currentProjectId);
  }, [currentView, language, currentProjectId]);

  // Global protection against saving/downloading images, videos, or content via context menu, drag, or save/inspect shortcuts
  useEffect(() => {
    const isFormElement = (el: HTMLElement | null) =>
      Boolean(
        el &&
          (el.tagName === 'INPUT' ||
            el.tagName === 'TEXTAREA' ||
            el.tagName === 'SELECT' ||
            el.isContentEditable)
      );

    const handleContextMenu = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!isFormElement(target)) {
        e.preventDefault();
      }
    };

    const handleDragStart = (e: DragEvent) => {
      e.preventDefault();
    };

    const handleCopyOrCut = (e: ClipboardEvent) => {
      const target = e.target as HTMLElement | null;
      if (!isFormElement(target)) {
        e.preventDefault();
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      const ctrlOrMeta = e.ctrlKey || e.metaKey;
      // Block Save Page (Cmd/Ctrl+S), View Source (Cmd/Ctrl+U), Print (Cmd/Ctrl+P), DevTools Inspect (Cmd/Ctrl+Shift+I/J/C, F12)
      if (
        (ctrlOrMeta && (key === 's' || key === 'u' || key === 'p')) ||
        (ctrlOrMeta && e.shiftKey && (key === 'i' || key === 'j' || key === 'c')) ||
        e.key === 'F12'
      ) {
        e.preventDefault();
      }
    };

    document.addEventListener('contextmenu', handleContextMenu);
    document.addEventListener('dragstart', handleDragStart);
    document.addEventListener('copy', handleCopyOrCut);
    document.addEventListener('cut', handleCopyOrCut);
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('contextmenu', handleContextMenu);
      document.removeEventListener('dragstart', handleDragStart);
      document.removeEventListener('copy', handleCopyOrCut);
      document.removeEventListener('cut', handleCopyOrCut);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  const handleNavigate = useCallback(
    (view: string, projectId?: string) => {
      const prefix = `/${language}`;
      setCurrentView(view);
      if (projectId) {
        setCurrentProjectId(projectId);
        const nextUrl = `${prefix}/project/${encodeURIComponent(projectId)}/`;
        window.history.pushState({ view, projectId, language }, '', nextUrl);
      } else {
        const nextUrl = view === 'home' ? `${prefix}/` : `${prefix}/${view}/`;
        window.history.pushState({ view, language }, '', nextUrl);
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
    },
    [language]
  );

  const handleSelectChapter = useCallback(
    (chapter: ChapterFilter) => {
      setActiveChapter(chapter);
      setCurrentView('work');
      const query = chapter !== 'all' ? `?chapter=${chapter}` : '';
      window.history.pushState({ view: 'work', chapter, language }, '', `/${language}/work/${query}`);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    },
    [language]
  );

  const handleToggleLanguage = () => {
    const nextLang: Language = language === 'en' ? 'sv' : 'en';
    setLanguage(nextLang);
    const prefix = `/${nextLang}`;
    const nextUrl =
      currentView === 'project'
        ? `${prefix}/project/${encodeURIComponent(currentProjectId)}/`
        : currentView === 'home'
          ? `${prefix}/`
          : currentView === 'work' && activeChapter !== 'all'
            ? `${prefix}/work/?chapter=${activeChapter}`
            : `${prefix}/${currentView}/`;
    window.history.pushState(
      { view: currentView, projectId: currentProjectId, language: nextLang, chapter: activeChapter },
      '',
      nextUrl
    );
  };

  const handleOpenLightbox = (asset: MediaAsset, projectGallery: MediaAsset[]) => {
    setLightboxAsset(asset);
    setLightboxGallery(projectGallery.length > 0 ? projectGallery : [asset]);
    setIsLightboxOpen(true);
  };

  const handleOpenVideo = (project: PortfolioProject) => {
    setVideoProject(project);
    setIsVideoModalOpen(true);
  };

  return (
    <div
      className="dino-ai-site min-h-screen flex flex-col font-sans selection:bg-white selection:text-black bg-[#07080a] text-[#f5f5f7]"
    >
      <a href="#main-content" className="skip-link">
        {language === 'sv' ? 'Hoppa till innehåll' : 'Skip to content'}
      </a>

      <Navbar
        currentView={currentView}
        onNavigate={handleNavigate}
        language={language}
        onToggleLanguage={handleToggleLanguage}
        activeChapter={activeChapter}
        onSelectChapter={handleSelectChapter}
        currentProjectId={currentView === 'project' ? currentProjectId : undefined}
      />

      <main id="main-content" tabIndex={-1} className="flex-1">
        {currentView === 'home' && (
          <HomeView
            language={language}
            onNavigate={handleNavigate}
            onSelectChapter={handleSelectChapter}
            onOpenLightbox={handleOpenLightbox}
            onOpenVideo={handleOpenVideo}
          />
        )}

        <React.Suspense fallback={null}>
          {currentView === 'work' && (
            <PortfolioView
              language={language}
              onNavigate={handleNavigate}
              onOpenLightbox={handleOpenLightbox}
              onOpenVideo={handleOpenVideo}
              activeChapter={activeChapter}
              onSelectChapter={setActiveChapter}
            />
          )}

          {currentView === 'project' && (
            <ProjectDetailView
              projectId={currentProjectId}
              language={language}
              onNavigate={handleNavigate}
              onOpenLightbox={handleOpenLightbox}
              onOpenVideo={handleOpenVideo}
            />
          )}

          {currentView === 'services' && (
            <ServicesView
              language={language}
              onNavigate={handleNavigate}
              onOpenLightbox={handleOpenLightbox}
              onOpenVideo={handleOpenVideo}
            />
          )}

          {currentView === 'about' && (
            <AboutView
              language={language}
              onNavigate={handleNavigate}
              onOpenLightbox={handleOpenLightbox}
              onOpenVideo={handleOpenVideo}
            />
          )}

          {currentView === 'contact' && (
            <ContactView
              language={language}
              onNavigate={handleNavigate}
            />
          )}

          {currentView === 'privacy' && (
            <PrivacyView
              language={language}
              onNavigate={handleNavigate}
            />
          )}
        </React.Suspense>
      </main>

      <LightboxModal
        asset={lightboxAsset}
        allAssets={lightboxGallery}
        isOpen={isLightboxOpen}
        onClose={() => setIsLightboxOpen(false)}
        language={language}
      />

      <VideoPlayerModal
        project={videoProject}
        isOpen={isVideoModalOpen}
        onClose={() => setIsVideoModalOpen(false)}
        language={language}
      />

      <Footer
        language={language}
        onNavigate={handleNavigate}
      />
    </div>
  );
}
