import React from 'react';

interface LogoProps {
  theme?: 'light' | 'dark' | 'auto';
  className?: string;
  showSubtitle?: boolean;
  interactive?: boolean;
  size?: 'sm' | 'md' | 'lg' | 'xl';
}

export const Logo: React.FC<LogoProps> = ({
  theme = 'light',
  className = '',
  showSubtitle = true,
  size = 'md'
}) => {
  const sizeConfig = {
    sm: 'h-8 sm:h-9',
    md: 'h-10 sm:h-11',
    lg: 'h-12 sm:h-14',
    xl: 'h-16 sm:h-20'
  };

  const isDark = theme === 'dark';
  const logoSrc = isDark
    ? '/brand/dino-logo-white-clean.png'
    : '/brand/dino-logo-black-clean.png';

  return (
    <div
      className={`inline-flex items-center gap-3.5 select-none ${className}`}
      onContextMenu={(e) => e.preventDefault()}
    >
      <img
        src={logoSrc}
        alt="Dino Studio"
        width={140}
        height={44}
        decoding="async"
        draggable={false}
        onDragStart={(e) => e.preventDefault()}
        className={`${sizeConfig[size]} w-auto object-contain block pointer-events-none select-none`}
      />

      {showSubtitle && (
        <div
          className={`hidden sm:flex flex-col justify-center text-left border-l pl-3.5 leading-tight ${
            isDark ? 'border-white/20' : 'border-black/15'
          }`}
        >
          <span
            className={`text-[10px] font-mono font-bold tracking-widest uppercase ${
              isDark ? 'text-white' : 'text-[#0a0a0c]'
            }`}
          >
            STOCKHOLM
          </span>
          <span
            className={`text-[8.5px] font-mono tracking-wider uppercase ${
              isDark ? 'text-[#8e929b]' : 'text-[#6b7280]'
            }`}
          >
            FILM · PHOTO · DIGITAL
          </span>
        </div>
      )}
    </div>
  );
};
