import React, { useState, useEffect } from 'react';
import { Menu, X, ArrowUpRight, Globe } from 'lucide-react';
import { Language } from '../types';
import { TRANSLATIONS } from '../data/translations';
import { Logo } from './Logo';

export type ChapterFilter = 'all' | 'sports' | 'editorial' | 'film' | 'digital';

interface NavbarProps {
  currentView: string;
  onNavigate: (view: string, projectId?: string) => void;
  language: Language;
  onToggleLanguage: () => void;
  activeChapter?: ChapterFilter;
  onSelectChapter?: (chapter: ChapterFilter) => void;
  currentProjectId?: string;
}

const isModifiedEvent = (e: React.MouseEvent) => {
  return e.metaKey || e.altKey || e.ctrlKey || e.shiftKey || e.button !== 0;
};

export const Navbar: React.FC<NavbarProps> = ({
  currentView,
  onNavigate,
  language,
  onToggleLanguage,
  activeChapter = 'all',
  onSelectChapter,
  currentProjectId,
}) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const t = TRANSLATIONS[language];

  const altLang: Language = language === 'en' ? 'sv' : 'en';
  const languageSwitchHref =
    currentView === 'project' && currentProjectId
      ? `/${altLang}/project/${encodeURIComponent(currentProjectId)}/`
      : currentView === 'home'
        ? `/${altLang}/`
        : `/${altLang}/${currentView}/${currentView === 'work' && activeChapter !== 'all' ? `?chapter=${activeChapter}` : ''}`;

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setMobileMenuOpen(false);
  }, [currentView, language]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setMobileMenuOpen(false);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const navItems = [
    { id: 'services', label: t.nav.services },
    { id: 'about', label: t.nav.about },
  ];

  const chapterItems: {
    id: Exclude<ChapterFilter, 'all'>;
    labelEn: string;
    labelSv: string;
  }[] = [
    {
      id: 'editorial',
      labelEn: '01 · Event & Photography',
      labelSv: '01 · Event & Fotografi',
    },
    {
      id: 'sports',
      labelEn: '02 · Sport & Arena',
      labelSv: '02 · Sport & Arena',
    },
    {
      id: 'film',
      labelEn: '03 · Film & Motion',
      labelSv: '03 · Film & Rörligt',
    },
    {
      id: 'digital',
      labelEn: '04 · Digital & Web',
      labelSv: '04 · Digitalt & Webb',
    },
  ];

  const handleNavClick = (viewId: string) => {
    if (viewId === 'work' && onSelectChapter) {
      onSelectChapter('all');
    } else {
      onNavigate(viewId);
    }
    setMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleChapterClick = (chapterId: ChapterFilter) => {
    if (onSelectChapter) {
      if (currentView === 'work' && activeChapter === chapterId && chapterId !== 'all') {
        onSelectChapter('all');
      } else {
        onSelectChapter(chapterId);
      }
    } else {
      onNavigate('work');
    }
    setMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <header
      className={`sticky top-0 z-40 transition-all duration-300 ${
        scrolled
          ? 'bg-[#07080a]/95 backdrop-blur-md border-b border-[#1e2026] text-white shadow-xl'
          : 'bg-[#07080a] border-b border-[#1e2026]/80 text-white'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div
          className={`flex items-center justify-between gap-3 transition-all duration-300 ${
            scrolled ? 'py-2.5' : 'py-3.5'
          }`}
        >
          {/* Brand Logo */}
          <div className="flex items-center shrink-0">
            <a
              href={`/${language}/`}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                handleNavClick('home');
              }}
              className="flex items-center text-left cursor-pointer focus:outline-hidden py-1"
              aria-label="Dino Studio Stockholm — Home"
            >
              <Logo theme="dark" size="sm" showSubtitle={false} interactive={true} />
            </a>
          </div>

          {/* Desktop Navigation: 01–04 Chapters (on xl+) + Services & About (on lg+) */}
          <nav
            className="hidden lg:flex items-center gap-2 2xl:gap-3 shrink-0"
            aria-label="Main navigation"
          >
            <div
              className="hidden xl:flex items-center gap-1 2xl:gap-1.5"
              role="group"
              aria-label={language === 'en' ? 'Portfolio chapters' : 'Portfoliokapitel'}
            >
              {chapterItems.map((ch) => {
                const isActive = currentView === 'work' && activeChapter === ch.id;
                return (
                  <a
                    key={ch.id}
                    href={`/${language}/work/?chapter=${ch.id}`}
                    onClick={(e) => {
                      if (isModifiedEvent(e)) return;
                      e.preventDefault();
                      handleChapterClick(ch.id);
                    }}
                    aria-current={isActive ? 'page' : undefined}
                    className={`shrink-0 px-2.5 py-1.5 rounded-full text-[10px] 2xl:text-[11px] font-mono uppercase tracking-normal 2xl:tracking-wide transition-all cursor-pointer flex items-center whitespace-nowrap ${
                      isActive
                        ? 'bg-white text-black font-bold shadow-lg'
                        : 'bg-white/5 text-white/75 hover:text-white hover:bg-white/10'
                    }`}
                  >
                    <span>{language === 'en' ? ch.labelEn : ch.labelSv}</span>
                  </a>
                );
              })}
            </div>

            <span className="hidden xl:inline-block h-4 w-px bg-white/15 mx-0.5 2xl:mx-1 shrink-0" aria-hidden="true" />

            <div className="flex items-center gap-4 xl:gap-3 2xl:gap-4 shrink-0">
              <a
                href={`/${language}/work/`}
                onClick={(e) => {
                  if (isModifiedEvent(e)) return;
                  e.preventDefault();
                  handleNavClick('work');
                }}
                className={`xl:hidden text-[11px] font-mono uppercase tracking-wider transition-colors cursor-pointer relative py-1 whitespace-nowrap focus:outline-hidden ${
                  currentView === 'work'
                    ? 'text-white font-bold'
                    : 'text-[#8e929d] hover:text-white'
                }`}
              >
                {t.nav.work}
                {currentView === 'work' && (
                  <span className="absolute bottom-0 left-0 w-full h-[2px] bg-white" />
                )}
              </a>
              {navItems.map((item) => {
                const isActive = currentView === item.id;
                return (
                  <a
                    key={item.id}
                    href={`/${language}/${item.id}/`}
                    onClick={(e) => {
                      if (isModifiedEvent(e)) return;
                      e.preventDefault();
                      handleNavClick(item.id);
                    }}
                    className={`text-[10px] 2xl:text-[11px] font-mono uppercase tracking-wider transition-colors cursor-pointer relative py-1 whitespace-nowrap focus:outline-hidden ${
                      isActive
                        ? 'text-white font-bold'
                        : 'text-[#8e929d] hover:text-white'
                    }`}
                  >
                    {item.label}
                    {isActive && (
                      <span className="absolute bottom-0 left-0 w-full h-[2px] bg-white" />
                    )}
                  </a>
                );
              })}
            </div>
          </nav>

          {/* Right Action: Language Switcher & Contact CTA */}
          <div className="hidden sm:flex items-center gap-1.5 2xl:gap-2.5 shrink-0">
            <a
              href={languageSwitchHref}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                onToggleLanguage();
              }}
              className="flex items-center gap-1 px-2 py-1.5 text-[10px] 2xl:text-[11px] font-mono font-medium rounded-xs text-[#8e929d] hover:text-white hover:bg-white/10 transition-colors cursor-pointer whitespace-nowrap"
              title={language === 'en' ? 'Byt till svenska' : 'Switch to English'}
              aria-label={language === 'en' ? 'EN / SV — Byt till svenska' : 'SV / EN — Switch to English'}
            >
              <Globe className="w-3.5 h-3.5 text-[#8e929d]" />
              <span>{language === 'en' ? 'EN / SV' : 'SV / EN'}</span>
            </a>

            <a
              href={`/${language}/contact/`}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                handleNavClick('contact');
              }}
              className="flex items-center gap-1.5 px-3 2xl:px-3.5 py-2 text-[10px] 2xl:text-[11px] font-mono font-bold tracking-wider uppercase transition-all duration-200 cursor-pointer shadow-sm bg-white hover:bg-neutral-200 text-black whitespace-nowrap"
            >
              <span>{t.nav.contact}</span>
              <ArrowUpRight className="w-3.5 h-3.5" />
            </a>
          </div>

          {/* Mobile / Tablet Menu Hamburger Button + Direct Mobile Quote CTA */}
          <div className="flex lg:hidden items-center gap-2 shrink-0">
            <a
              href={`/${language}/contact/`}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                handleNavClick('contact');
              }}
              className="sm:hidden px-2.5 py-1.5 bg-white text-black font-mono text-[10px] font-bold uppercase tracking-wider rounded-xs whitespace-nowrap"
            >
              {language === 'sv' ? 'Offert' : 'Quote'}
            </a>

            <a
              href={languageSwitchHref}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                onToggleLanguage();
              }}
              className="sm:hidden p-2 rounded-xs font-mono text-xs text-white hover:bg-white/10"
              aria-label={language === 'en' ? 'SV — Byt till svenska' : 'EN — Switch to English'}
            >
              {language === 'en' ? 'SV' : 'EN'}
            </a>

            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="p-2 rounded-xs transition-colors cursor-pointer text-white hover:bg-white/10"
              aria-expanded={mobileMenuOpen}
              aria-controls="mobile-menu"
              aria-label={
                language === 'sv'
                  ? mobileMenuOpen
                    ? 'Stäng meny'
                    : 'Öppna meny'
                  : mobileMenuOpen
                    ? 'Close menu'
                    : 'Open menu'
              }
            >
              {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {/* Sub-desktop (< xl) Quick Chapter Filter Bar so 01–04 never crowd the top header */}
        <div
          className="flex xl:hidden items-center gap-1.5 overflow-x-auto pb-2.5 pt-0.5 no-scrollbar w-full min-w-0 max-w-full"
          role="group"
          aria-label={language === 'en' ? 'Portfolio chapters' : 'Portfoliokapitel'}
        >
          {chapterItems.map((ch) => {
            const isActive = currentView === 'work' && activeChapter === ch.id;
            return (
              <a
                key={ch.id}
                href={`/${language}/work/?chapter=${ch.id}`}
                onClick={(e) => {
                  if (isModifiedEvent(e)) return;
                  e.preventDefault();
                  handleChapterClick(ch.id);
                }}
                className={`shrink-0 px-2.5 py-1.5 rounded-full text-[10px] font-mono uppercase tracking-normal transition-all cursor-pointer flex items-center whitespace-nowrap ${
                  isActive
                    ? 'bg-white text-black font-bold shadow-sm'
                    : 'bg-white/8 text-white/80 hover:text-white'
                }`}
              >
                <span>{language === 'en' ? ch.labelEn : ch.labelSv}</span>
              </a>
            );
          })}
        </div>
      </div>

      {/* Mobile / Tablet Dropdown Menu */}
      {mobileMenuOpen && (
        <div
          id="mobile-menu"
          className="lg:hidden max-h-[calc(100dvh-115px)] overflow-y-auto border-t border-[#1e2026] bg-[#0a0b0e] text-white px-4 pt-4 pb-6 space-y-4 shadow-xl animate-in fade-in duration-200"
        >
          <div className="space-y-1">
            <a
              href={`/${language}/`}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                handleNavClick('home');
              }}
              className={`block w-full text-left px-3 py-2 text-base font-display font-medium rounded-xs cursor-pointer ${
                currentView === 'home'
                  ? 'bg-white/10 text-white font-bold'
                  : 'text-[#b0b4be] hover:text-white'
              }`}
            >
              {t.nav.home}
            </a>

            <a
              href={`/${language}/work/`}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                handleNavClick('work');
              }}
              className={`block w-full text-left px-3 py-2 text-base font-display font-medium rounded-xs cursor-pointer ${
                currentView === 'work' && activeChapter === 'all'
                  ? 'bg-white/10 text-white font-bold'
                  : 'text-[#b0b4be] hover:text-white'
              }`}
            >
              {t.nav.work}
            </a>

            <div className="py-2 space-y-1.5 border-y border-white/10 my-2">
              {chapterItems.map((ch) => {
                const isActive = currentView === 'work' && activeChapter === ch.id;
                return (
                  <a
                    key={ch.id}
                    href={`/${language}/work/?chapter=${ch.id}`}
                    onClick={(e) => {
                      if (isModifiedEvent(e)) return;
                      e.preventDefault();
                      handleChapterClick(ch.id);
                    }}
                    className={`block w-full text-left px-3 py-2 text-xs font-mono uppercase tracking-wider rounded-lg cursor-pointer ${
                      isActive
                        ? 'bg-white text-black font-bold'
                        : 'text-white/80 hover:bg-white/10'
                    }`}
                  >
                    {language === 'en' ? ch.labelEn : ch.labelSv}
                  </a>
                );
              })}
            </div>

            {navItems.map((item) => (
              <a
                key={item.id}
                href={`/${language}/${item.id}/`}
                onClick={(e) => {
                  if (isModifiedEvent(e)) return;
                  e.preventDefault();
                  handleNavClick(item.id);
                }}
                className={`block w-full text-left px-3 py-2 text-base font-display font-medium rounded-xs cursor-pointer ${
                  currentView === item.id
                    ? 'bg-white/10 text-white font-bold'
                    : 'text-[#b0b4be] hover:text-white'
                }`}
              >
                {item.label}
              </a>
            ))}
          </div>

          <div className="pt-2 border-t border-white/10">
            <a
              href={`/${language}/contact/`}
              onClick={(e) => {
                if (isModifiedEvent(e)) return;
                e.preventDefault();
                handleNavClick('contact');
              }}
              className="block w-full py-3 bg-white text-black font-mono text-xs font-bold uppercase tracking-wider text-center cursor-pointer hover:bg-neutral-200"
            >
              {t.nav.contact}
            </a>
          </div>
        </div>
      )}
    </header>
  );
};
