import React, { useEffect, useState, useCallback } from 'react';
import { X, ChevronLeft, ChevronRight, Maximize2, Minimize2, Info } from 'lucide-react';
import { MediaAsset, Language } from '../types';
import { useModalFocus } from '../hooks/useModalFocus';

interface LightboxModalProps {
  asset: MediaAsset | null;
  allAssets: MediaAsset[];
  isOpen: boolean;
  onClose: () => void;
  language: Language;
}

export const LightboxModal: React.FC<LightboxModalProps> = ({
  asset,
  allAssets,
  isOpen,
  onClose,
  language
}) => {
  const dialogRef = useModalFocus(isOpen);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isZoomed, setIsZoomed] = useState(false);
  const [showMetadata, setShowMetadata] = useState(true);
  const touchStartXRef = React.useRef<number | null>(null);

  useEffect(() => {
    if (asset && allAssets.length > 0) {
      const idx = allAssets.findIndex((a) => a.id === asset.id || a.url === asset.url);
      setCurrentIndex(idx !== -1 ? idx : 0);
    }
    setIsZoomed(false);
  }, [asset, allAssets]);

  // Preload adjacent images so left/right navigation is instant
  useEffect(() => {
    if (!isOpen || allAssets.length <= 1) return;
    const indicesToPreload = [
      (currentIndex + 1) % allAssets.length,
      (currentIndex - 1 + allAssets.length) % allAssets.length,
      (currentIndex + 2) % allAssets.length,
      (currentIndex - 2 + allAssets.length) % allAssets.length
    ];
    indicesToPreload.forEach((idx) => {
      const target = allAssets[idx];
      if (target?.url) {
        const img = new Image();
        img.src = target.url;
      }
    });
  }, [isOpen, currentIndex, allAssets]);

  const handleNext = useCallback(() => {
    if (allAssets.length <= 1) return;
    setIsZoomed(false);
    setCurrentIndex((prev) => (prev + 1) % allAssets.length);
  }, [allAssets.length]);

  const handlePrev = useCallback(() => {
    if (allAssets.length <= 1) return;
    setIsZoomed(false);
    setCurrentIndex((prev) => (prev - 1 + allAssets.length) % allAssets.length);
  }, [allAssets.length]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return;
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowRight') {
        e.preventDefault();
        handleNext();
      }
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        handlePrev();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose, handleNext, handlePrev]);

  if (!isOpen || !asset) return null;

  const current = allAssets[currentIndex] || asset;

  return (
    <div
      ref={dialogRef}
      tabIndex={-1}
      className="fixed inset-0 z-50 bg-[#050608]/95 backdrop-blur-xl flex flex-col justify-between p-4 sm:p-8 text-white select-none"
      role="dialog"
      aria-modal="true"
      aria-label={language === 'sv' ? 'Bildvisare' : 'Full-resolution image viewer'}
      onContextMenu={(e) => e.preventDefault()}
    >
      {/* Top Minimal Floating Bar */}
      <div className="flex items-center justify-between z-20">
        <div className="flex items-center gap-3 text-xs font-mono">
          <span className="text-white font-bold">
            {String(currentIndex + 1).padStart(2, '0')} / {String(allAssets.length).padStart(2, '0')}
          </span>
          <span className="text-white/20" aria-hidden="true">·</span>
          <span className="text-white/60">
            {current.aspectRatio}
          </span>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowMetadata(!showMetadata)}
            aria-label={language === 'sv' ? 'Bildinformation' : 'Image details'}
            aria-pressed={showMetadata}
            className={`px-3 py-1.5 rounded-full text-xs font-mono flex items-center gap-1.5 transition-colors cursor-pointer ${
              showMetadata ? 'bg-white/15 text-white' : 'text-white/65 hover:text-white hover:bg-white/10'
            }`}
          >
            <Info className="w-3.5 h-3.5" />
            <span className="hidden sm:inline">
              {language === 'en' ? 'Details' : 'Detaljer'}
            </span>
          </button>

          <button
            onClick={() => setIsZoomed(!isZoomed)}
            className="p-2 text-white/60 hover:text-white hover:bg-white/10 rounded-full transition-colors cursor-pointer"
            title={isZoomed ? 'Fit to Screen' : 'Zoom'}
          >
            {isZoomed ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
          </button>

          <button
            onClick={onClose}
            className="p-2 text-white/80 hover:text-white hover:bg-white/15 rounded-full transition-colors cursor-pointer"
            aria-label={language === 'sv' ? 'Stäng bildvisaren' : 'Close image viewer'}
          >
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Main Center Stage: Frameless Native Aspect Ratio Image */}
      <div
        className="relative flex-1 flex items-center justify-center my-2 overflow-hidden"
        onTouchStart={(e) => {
          touchStartXRef.current = e.touches[0]?.clientX ?? null;
        }}
        onTouchEnd={(e) => {
          if (touchStartXRef.current === null || allAssets.length <= 1) return;
          const endX = e.changedTouches[0]?.clientX ?? touchStartXRef.current;
          const diff = endX - touchStartXRef.current;
          touchStartXRef.current = null;
          if (Math.abs(diff) > 40) {
            if (diff < 0) handleNext();
            else handlePrev();
          }
        }}
      >
        {allAssets.length > 1 && (
          <>
            <button
              onClick={handlePrev}
              className="absolute left-2 sm:left-6 z-30 p-3.5 bg-white/10 hover:bg-white text-white hover:text-black rounded-full backdrop-blur-md transition-all cursor-pointer focus:outline-hidden shadow-lg"
              aria-label={language === 'sv' ? 'Föregående bild' : 'Previous image'}
            >
              <ChevronLeft className="w-6 h-6" />
            </button>
            <button
              onClick={handleNext}
              className="absolute right-2 sm:right-6 z-30 p-3.5 bg-white/10 hover:bg-white text-white hover:text-black rounded-full backdrop-blur-md transition-all cursor-pointer focus:outline-hidden shadow-lg"
              aria-label={language === 'sv' ? 'Nästa bild' : 'Next image'}
            >
              <ChevronRight className="w-6 h-6" />
            </button>
          </>
        )}

        <div
          className={`relative transition-transform duration-200 ${
            isZoomed ? 'scale-125 cursor-zoom-out' : 'cursor-zoom-in'
          }`}
          data-protected-media="true"
        >
          <img
            key={current.url}
            src={current.url}
            alt={`${language === 'en' ? current.titleEn : current.titleSv} – photo by Dino / Dino Studio`}
            draggable={false}
            onDragStart={(e) => e.preventDefault()}
            onContextMenu={(e) => e.preventDefault()}
            onClick={() => setIsZoomed(!isZoomed)}
            className="max-h-[78vh] max-w-[90vw] w-auto h-auto object-contain rounded-2xl shadow-2xl select-none pointer-events-none"
          />
          <div
            onClick={() => setIsZoomed(!isZoomed)}
            onContextMenu={(e) => e.preventDefault()}
            onDragStart={(e) => e.preventDefault()}
            className="absolute inset-0 z-10 rounded-2xl select-none flex items-end justify-end p-3"
          >
            <span className="px-2.5 py-1 rounded-full bg-black/55 backdrop-blur-xs text-[10px] font-mono tracking-wider text-white/75 pointer-events-none select-none">
              © Dino Studio · dinostudio.se
            </span>
          </div>
        </div>
      </div>

      {/* Frameless Floating Caption */}
      {showMetadata && (
        <div className="max-w-4xl mx-auto w-full flex flex-col sm:flex-row items-start sm:items-end justify-between gap-4 text-xs z-20 pt-2">
          <div className="space-y-1 max-w-xl">
            <h2 className="font-display font-bold text-white text-base">
              {language === 'en' ? current.titleEn : current.titleSv}
            </h2>
            {(current.captionEn || current.captionSv) && (
              <p className="text-white/60 leading-relaxed">
                {language === 'en' ? current.captionEn : current.captionSv}
              </p>
            )}
          </div>
        </div>
      )}
    </div>
  );
};
