/**
 * Shared SEO metadata serialization and text formatting utilities.
 * Used identically at build-time (scripts/generate-seo-routes.mjs)
 * and client-side (src/App.tsx).
 */

const SHORT_CATEGORY_LABELS = new Set([
  'på scen',
  'on stage',
  'mode / film',
  'fashion / film',
  'event / scen',
  'event / stage',
  'musik / scen',
  'music / stage',
  'logotyp / ljus',
  'logo / light',
  'logotyp / guld',
  'logo / gold',
]);

/**
 * Escapes characters for safe inclusion in HTML text and attribute values.
 */
export function escapeHtml(str: string): string {
  if (!str) return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Safely serializes an object to JSON-LD for embedding inside a <script> element.
 * Escapes angle brackets and ampersands to prevent script tag injection and XML issues.
 */
export function safeJsonLdString(obj: unknown): string {
  return JSON.stringify(obj, null, 2)
    .replace(/</g, '\\u003c')
    .replace(/>/g, '\\u003e')
    .replace(/&/g, '\\u0026')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029');
}

/**
 * Cleanly truncates a string on a word boundary, avoiding mid-word cuts.
 */
export function truncateClean(str: string, max = 160): string {
  if (!str) return '';
  const clean = str.replace(/\s+/g, ' ').trim();
  if (clean.length <= max) return clean;
  const cut = clean.slice(0, max);
  const lastSpace = cut.lastIndexOf(' ');
  return lastSpace > 100 ? `${cut.slice(0, lastSpace)}...` : `${cut}...`;
}

export interface ProjectLike {
  title: string;
  summarySv?: string;
  summaryEn?: string;
  narrativeSv?: string;
  narrativeEn?: string;
}

/**
 * Generates an informative, consistent description for a project across build-time
 * static HTML and client-side dynamic metadata.
 * Prefers narrative when summary is only a short generic label (e.g., "På scen" / "On stage").
 */
export function getProjectDescription(project: ProjectLike, lang: 'sv' | 'en'): string {
  const isSv = lang === 'sv';
  const summary = (isSv ? project.summarySv : project.summaryEn)?.trim() || '';
  const narrative = (isSv ? project.narrativeSv : project.narrativeEn)?.trim() || '';

  const summaryLower = summary.toLowerCase();
  const isShortLabel =
    SHORT_CATEGORY_LABELS.has(summaryLower) || (summary.length > 0 && summary.length < 15 && !summary.includes('.'));

  let chosen = '';
  if (isShortLabel && narrative && narrative.length > summary.length) {
    chosen = narrative;
  } else if (summary) {
    chosen = summary;
  } else if (narrative) {
    chosen = narrative;
  }

  if (chosen) {
    return truncateClean(chosen, 160);
  }

  return isSv
    ? `Se foton och videodokumentation från ${project.title} av Dino Studio i Stockholm.`
    : `Explore visual documentation and photography from ${project.title} by Dino Studio in Stockholm.`;
}

/**
 * Returns the standardized, consistent project page title.
 */
export function getProjectTitle(project: { title: string }): string {
  return `${project.title} — Dino Studio Stockholm`;
}

export interface PageMetadataResult {
  title: string;
  description: string;
  canonicalPath: string;
  ogImage: string;
}

/**
 * Returns the canonical SEO metadata for any view and language.
 * Shared across build-time prerendering and client-side navigation.
 */
export function getPageMetadata(
  view: string,
  language: 'sv' | 'en',
  project?: {
    id: string;
    slug?: string;
    title: string;
    summarySv?: string;
    summaryEn?: string;
    narrativeSv?: string;
    narrativeEn?: string;
    coverAsset?: { url: string };
  }
): PageMetadataResult {
  const isSv = language === 'sv';
  const defaultOgImage = 'https://dinostudio.se/images/event-1513.webp';

  let title = isSv
    ? 'Dino Studio | Eventfoto & Film i Stockholm'
    : 'Dino Studio | Event Photography & Film in Stockholm';
  let description = isSv
    ? 'Eventfoto och film för företag och organisationer i Stockholm. Fotoreportage, highlightfilmer, porträtt och kompletterande sportbevakning från Dino Studio.'
    : 'Event photography and film for companies and organisations in Stockholm. Photo reportage, highlight films, portraits, and supporting sports coverage by Dino Studio.';
  let canonicalPath = '/';
  let ogImage = defaultOgImage;

  if (view === 'work') {
    title = isSv
      ? 'Utvalda arbeten — Eventfoto & Film | Dino Studio Stockholm'
      : 'Selected Work — Event Photography & Film | Dino Studio Stockholm';
    description = isSv
      ? 'Utforska eventfoto och film för företag och organisationer i Stockholm, porträtt, scenproduktioner och kompletterande sportbildjournalistik från Dino Studio.'
      : 'Explore event photography and film for companies and organisations in Stockholm, portraits, stage documentation, and supporting sports coverage by Dino Studio.';
    canonicalPath = '/work';
  } else if (view === 'services') {
    title = isSv
      ? 'Tjänster — Eventfoto, Porträtt, Film & Design | Dino Studio'
      : 'Services — Event Photography, Portraits & Film | Dino Studio';
    description = isSv
      ? 'Eventfotografering, korta highlightfilmer, porträtt- och produktfoto, löpande innehåll och digital design för företag och organisationer i Stockholm.'
      : 'Event photography, short highlight films, portrait and product photography, recurring content, and digital design for companies and organisations in Stockholm.';
    canonicalPath = '/services';
  } else if (view === 'about') {
    title = isSv
      ? 'Om studion — Dino · Fotografi & Film | Dino Studio'
      : 'About the Studio — Dino · Photography & Film | Dino Studio';
    description = isSv
      ? 'Dino Studio drivs av Dino — fotograf, filmare och bildjournalist i Stockholm med fokus på eventfoto och film för företag och organisationer.'
      : 'Dino Studio is run by Dino — photographer, filmmaker and photojournalist in Stockholm working across event photography, film and photojournalism.';
    canonicalPath = '/about';
  } else if (view === 'contact') {
    title = isSv
      ? 'Skicka en förfrågan — Kontakta Dino Studio Stockholm'
      : 'Send an Enquiry — Contact Dino Studio Stockholm';
    description = isSv
      ? 'Skicka en förfrågan om eventfotografering, highlightfilm, porträtt, produktfoto eller digital design i Stockholm.'
      : 'Send an enquiry for event photography, highlight films, portraits, product photography, or digital design in Stockholm.';
    canonicalPath = '/contact';
  } else if (view === 'privacy') {
    title = isSv
      ? 'Integritetspolicy (GDPR) | Dino Studio Stockholm'
      : 'Privacy Policy (GDPR) | Dino Studio Stockholm';
    description = isSv
      ? 'Integritetspolicy för kontaktformulär och kundförfrågningar hos Dino Studio i Stockholm.'
      : 'Privacy policy for contact enquiries and personal data processing at Dino Studio in Stockholm.';
    canonicalPath = '/privacy';
  } else if (view === 'project' && project) {
    title = getProjectTitle(project);
    description = getProjectDescription(project, language);
    canonicalPath = `/project/${project.slug || project.id}`;
    if (project.coverAsset?.url) {
      ogImage = project.coverAsset.url.startsWith('/')
        ? `https://dinostudio.se${project.coverAsset.url}`
        : project.coverAsset.url;
    }
  }

  const prefix = isSv ? '/sv' : '/en';
  const fullCanonicalPath = `${prefix}${canonicalPath === '/' ? '/' : `${canonicalPath}/`}`;

  return {
    title,
    description,
    canonicalPath: fullCanonicalPath,
    ogImage,
  };
}
