export const BrandsMarquee: React.FC<BrandsMarqueeProps> = ({ language, onNavigate }) => {
  const isSv = language === 'sv';
  const marqueeList = [...PORTFOLIO_BRAND_ITEMS, ...PORTFOLIO_BRAND_ITEMS];

  return (
    <section
      aria-label={
        isSv
          ? 'Utvalda samarbeten, publiceringar och organisationer'
          : 'Selected collaborations, publications and organisations'
      }
      className="relative bg-[#07080a] border-t border-white/10 py-8 overflow-hidden select-none"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-3 flex items-center justify-between gap-4">
        <p className="text-[11px] sm:text-xs font-mono uppercase tracking-wider text-white/65">
          {isSv
            ? 'Ur portfolion · Uppdrag, samarbeten, publiceringar och bevakade evenemang'
            : 'From the portfolio · Assignments, collaborations, publications and covered events'}
        </p>
      </div>

      {/* Horizontal Logo Marquee Container with Seamless Same-Background Fade Masks */}
      <div className="relative w-full overflow-clip [contain:paint] bg-[#07080a] py-2">
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 left-0 z-10 w-20 sm:w-36 bg-gradient-to-r from-[#07080a] via-[#07080a]/90 to-transparent"
        />
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 right-0 z-10 w-20 sm:w-36 bg-gradient-to-l from-[#07080a] via-[#07080a]/90 to-transparent"
        />

        <div className="animate-brands-marquee items-center">
          {marqueeList.map((item, idx) => {
            const isDuplicate = idx >= PORTFOLIO_BRAND_ITEMS.length;
            const tagLabel = item.category
              ? isSv
                ? CATEGORY_LABELS[item.category].sv
                : CATEGORY_LABELS[item.category].en
              : null;

            const innerContent = (
              <div className="flex flex-col items-center justify-center gap-2">
                <div className="h-14 flex items-center justify-center">
                  <img
                    src={item.logoSrc}
                    alt={`${item.name} – photo by Dino Bavehjani / Dino Studio`}
                    width={160}
                    height={56}
                    loading="lazy"
                    decoding="async"
                    draggable={false}
                    onContextMenu={(e) => e.preventDefault()}
                    className={`${item.heightClass} w-auto object-contain select-none pointer-events-none`}
                  />
                </div>
                <div className="h-4 flex items-center justify-center">
                  {tagLabel && (
                    <span className="text-[10px] font-mono font-semibold uppercase tracking-[0.14em] text-white/75 whitespace-nowrap">
                      {tagLabel}
                    </span>
                  )}
                </div>
              </div>
            );

            return (
              <div
                key={`${item.id}-${idx}`}
                aria-hidden={isDuplicate ? true : undefined}
                inert={isDuplicate ? true : undefined}
                className="flex items-center"
              >
                {item.externalUrl ? (
                  <a
                    href={item.externalUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    title={item.name}
                    aria-label={tagLabel ? `${item.name} — ${tagLabel}` : item.name}
                    onClick={(e) => {
                      e.currentTarget.blur();
                    }}
                    className="group px-8 sm:px-12 py-2 flex items-center justify-center opacity-90 hover:opacity-100 transition-opacity duration-300 cursor-pointer focus:outline-hidden"
                  >
                    {innerContent}
                  </a>
                ) : (
                  <a
                    href={item.projectId ? `/${language}/project/${item.projectId}/` : `/${language}/work/`}
                    title={item.name}
                    aria-label={tagLabel ? `${item.name} — ${tagLabel}` : item.name}
                    onClick={(e) => {
                      e.currentTarget.blur();
                      if (
                        e.button === 0 &&
                        !e.metaKey &&
                        !e.ctrlKey &&
                        !e.shiftKey &&
                        !e.altKey &&
                        onNavigate &&
                        item.projectId
                      ) {
                        e.preventDefault();
                        onNavigate('project', item.projectId);
                        window.scrollTo({ top: 0, behavior: 'smooth' });
                      }
                    }}
                    className="group px-8 sm:px-12 py-2 flex items-center justify-center opacity-90 hover:opacity-100 transition-opacity duration-300 cursor-pointer focus:outline-hidden"
                  >
                    {innerContent}
                  </a>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};
