import React, { useEffect, useRef, useState } from 'react';

interface AutoPlayVideoProps {
  src: string;
  poster?: string;
  startTime?: number;
  muted?: boolean;
  retryWhenVisibleOnMobile?: boolean;
  className?: string;
  fetchPriority?: 'high' | 'low' | 'auto';
}

export const AutoPlayVideo: React.FC<AutoPlayVideoProps> = ({
  src,
  poster,
  startTime = 0,
  muted = true,
  className = '',
  fetchPriority,
}) => {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [inView, setInView] = useState<boolean>(false);
  const [isVideoReady, setIsVideoReady] = useState<boolean>(false);

  useEffect(() => {
    setIsVideoReady(false);
  }, [src]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        setInView(entry.isIntersecting);
        if (!entry.isIntersecting) {
          video.pause();
        }
      },
      { rootMargin: '300px 0px', threshold: 0.01 }
    );

    observer.observe(video);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const video = videoRef.current;
    if (!video || !inView) return;

    const handleLoadedMetadata = () => {
      if (startTime > 0 && video.currentTime < 0.5) {
        try {
          video.currentTime = startTime;
        } catch {
          // Ignore seek errors before buffer
        }
      }
    };

    const tryPlay = () => {
      if (document.hidden) return;
      video.defaultMuted = muted;
      video.muted = muted;
      video.playsInline = true;
      video.play().catch(() => {});
    };

    const handlePlaying = () => {
      setIsVideoReady(true);
    };

    const handleTimeUpdate = () => {
      if (video.currentTime > 0.05) {
        setIsVideoReady(true);
      }
    };

    video.addEventListener('loadedmetadata', handleLoadedMetadata);
    video.addEventListener('canplay', tryPlay);
    video.addEventListener('playing', handlePlaying);
    video.addEventListener('timeupdate', handleTimeUpdate);
    window.addEventListener('pageshow', tryPlay);
    document.addEventListener('visibilitychange', tryPlay);
    tryPlay();

    return () => {
      video.removeEventListener('loadedmetadata', handleLoadedMetadata);
      video.removeEventListener('canplay', tryPlay);
      video.removeEventListener('playing', handlePlaying);
      video.removeEventListener('timeupdate', handleTimeUpdate);
      window.removeEventListener('pageshow', tryPlay);
      document.removeEventListener('visibilitychange', tryPlay);
    };
  }, [src, inView, muted, startTime]);

  const isHeroPoster = Boolean(poster && poster.includes('video-nile-rodgers-chic'));
  const srcSet = isHeroPoster
    ? '/video-frames/video-nile-rodgers-chic-768w.webp 768w, /video-frames/video-nile-rodgers-chic.webp 1920w'
    : undefined;
  const sizes = isHeroPoster ? '100vw' : undefined;

  return (
    <>
      {poster && (
        <img
          src={poster}
          srcSet={srcSet}
          sizes={sizes}
          width={1280}
          height={720}
          alt=""
          aria-hidden="true"
          draggable={false}
          loading={fetchPriority === 'high' ? 'eager' : 'lazy'}
          decoding="async"
          onContextMenu={(e) => e.preventDefault()}
          onDragStart={(e) => e.preventDefault()}
          fetchPriority={fetchPriority}
          className={`${className} ${
            isVideoReady ? 'opacity-0 pointer-events-none absolute inset-0' : 'opacity-100'
          } transition-opacity duration-500`}
        />
      )}
      <video
        ref={videoRef}
        src={inView ? src : undefined}
        poster={inView && !srcSet ? poster : undefined}
        autoPlay={inView}
        muted={muted}
        loop
        playsInline
        preload={inView ? 'metadata' : 'none'}
        controlsList="nodownload noplaybackrate noremoteplayback"
        disablePictureInPicture
        disableRemotePlayback
        onContextMenu={(e) => e.preventDefault()}
        onDragStart={(e) => e.preventDefault()}
        className={`${className} ${
          poster && !isVideoReady ? 'opacity-0 pointer-events-none absolute inset-0' : 'opacity-100'
        }`}
      />
    </>
  );
};
