import React, { useEffect } from 'react';
import { X, ExternalLink } from 'lucide-react';
import { PortfolioProject, Language } from '../types';
import { useModalFocus } from '../hooks/useModalFocus';

interface VideoPlayerModalProps {
  project: PortfolioProject | null;
  isOpen: boolean;
  onClose: () => void;
  language: Language;
}

export const VideoPlayerModal: React.FC<VideoPlayerModalProps> = ({
  project,
  isOpen,
  onClose,
  language
}) => {
  const dialogRef = useModalFocus(isOpen);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isOpen && e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen || !project) return null;

  return (
    <div
      ref={dialogRef}
      tabIndex={-1}
      className="fixed inset-0 z-50 bg-[#050608]/95 backdrop-blur-xl flex flex-col justify-between p-4 sm:p-8 text-white select-none"
      role="dialog"
      aria-modal="true"
      aria-label={language === 'sv' ? 'Filmspelare' : 'Video screening player'}
      onContextMenu={(e) => e.preventDefault()}
    >
      {/* Top Floating Bar */}
      <div className="flex items-center justify-between z-20">
        <div className="flex items-center gap-3 text-xs font-mono">
          <span className="text-white font-bold uppercase tracking-widest">
            {project.title}
          </span>
          <span className="text-white/20" aria-hidden="true">·</span>
          <span className="text-white/60">
            {project.coverAsset.aspectRatio}
          </span>
        </div>

        <button
          onClick={onClose}
          className="p-2 text-white/80 hover:text-white hover:bg-white/15 rounded-full transition-colors cursor-pointer"
          aria-label={language === 'sv' ? 'Stäng filmspelaren' : 'Close video player'}
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Frameless Native Aspect Ratio Video Stage (16:9, 9:16, 1:1 with zero side-box padding) */}
      <div
        className="relative flex-1 flex items-center justify-center my-4 overflow-hidden"
        data-protected-media="true"
      >
        {project.externalVideoUrl ? (
          <video
            key={project.externalVideoUrl}
            src={project.externalVideoUrl}
            poster={project.coverAsset.url}
            controls
            controlsList="nodownload noplaybackrate noremoteplayback"
            disablePictureInPicture
            disableRemotePlayback
            autoPlay
            playsInline
            preload="metadata"
            onContextMenu={(e) => e.preventDefault()}
            onDragStart={(e) => e.preventDefault()}
            className="max-h-[76vh] max-w-[90vw] w-auto h-auto object-contain rounded-2xl shadow-2xl mx-auto"
          />
        ) : (
          <img
            src={project.coverAsset.url}
            alt={project.title}
            draggable={false}
            onContextMenu={(e) => e.preventDefault()}
            className="max-h-[76vh] max-w-[90vw] w-auto h-auto object-contain rounded-2xl shadow-2xl mx-auto"
          />
        )}
      </div>

      {/* Bottom Floating Information */}
      <div className="max-w-5xl mx-auto w-full flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 text-xs z-20">
        <div className="space-y-1">
          <h2 className="font-display font-bold text-white text-base">
            {project.title}
          </h2>
          <div className="flex flex-wrap items-center gap-2 text-xs text-white/65 font-mono">
            <span>{project.clientOrSubject}</span>
            <span aria-hidden="true">·</span>
            <span>{project.location}</span>
            <span aria-hidden="true">·</span>
            <span>{project.year}</span>
          </div>
        </div>

        <a
          href="mailto:info@dinostudio.se?subject=Video%20Production%20Enquiry%20%E2%80%94%20Dino%20Studio"
          className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white text-white hover:text-black font-mono text-xs rounded-full transition-colors"
        >
          <span>{language === 'en' ? 'Enquire About Production' : 'Förfrågan om produktion'}</span>
          <ExternalLink className="w-3.5 h-3.5" />
        </a>
      </div>
    </div>
  );
};
