import React from 'react';
import { Language } from '../types';

export interface TestimonialSlot {
  id: string;
  quoteEn: string;
  quoteSv: string;
  author: string;
  roleEn: string;
  roleSv: string;
  organization: string;
}

/**
 * Step 3D: Three testimonial slots for real client quotes.
 * Leave quoteEn / quoteSv empty until verified quotes are provided.
 * When all slots are empty, <Testimonials /> renders nothing (null).
 */
export const TESTIMONIAL_SLOTS: TestimonialSlot[] = [
  {
    id: 'slot-1',
    // TODO: Add verified client quote #1 (e.g. event organiser or institution)
    quoteEn: '',
    quoteSv: '',
    author: '',
    roleEn: '',
    roleSv: '',
    organization: '',
  },
  {
    id: 'slot-2',
    // TODO: Add verified client quote #2 (e.g. concert or cultural producer)
    quoteEn: '',
    quoteSv: '',
    author: '',
    roleEn: '',
    roleSv: '',
    organization: '',
  },
  {
    id: 'slot-3',
    // TODO: Add verified client quote #3 (e.g. sports club, federation, or brand)
    quoteEn: '',
    quoteSv: '',
    author: '',
    roleEn: '',
    roleSv: '',
    organization: '',
  },
];

export function getActiveTestimonials(slots: TestimonialSlot[] = TESTIMONIAL_SLOTS): TestimonialSlot[] {
  return slots.filter(
    (slot) =>
      (slot.quoteEn.trim().length > 0 || slot.quoteSv.trim().length > 0) &&
      slot.author.trim().length > 0
  );
}

interface TestimonialsProps {
  language: Language;
  slots?: TestimonialSlot[];
}

export const Testimonials: React.FC<TestimonialsProps> = ({
  language,
  slots = TESTIMONIAL_SLOTS,
}) => {
  const activeQuotes = getActiveTestimonials(slots);

  // Step 3D requirement: If no real quote is provided, the component must render nothing.
  if (activeQuotes.length === 0) {
    return null;
  }

  return (
    <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-10">
      <div className="space-y-2 border-b border-white/10 pb-6">
        <span className="text-xs font-mono uppercase tracking-widest text-[#f59e0b] block">
          {language === 'en' ? 'CLIENT FEEDBACK' : 'UPPDRAGSGIVARE'}
        </span>
        <h2 className="font-display text-3xl sm:text-4xl font-bold text-white">
          {language === 'en' ? 'What clients say.' : 'Ord från uppdragsgivare.'}
        </h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {activeQuotes.map((item) => (
          <blockquote
            key={item.id}
            className="bg-white/[0.03] border border-white/10 rounded-2xl p-6 sm:p-8 flex flex-col justify-between space-y-6"
          >
            <p className="text-base text-white/85 leading-relaxed font-light">
              “{language === 'en' ? item.quoteEn || item.quoteSv : item.quoteSv || item.quoteEn}”
            </p>
            <footer className="text-xs font-mono space-y-1 border-t border-white/10 pt-4">
              <div className="text-white font-bold">{item.author}</div>
              <div className="text-white/55">
                {language === 'en' ? item.roleEn : item.roleSv}
                {item.organization ? ` · ${item.organization}` : ''}
              </div>
            </footer>
          </blockquote>
        ))}
      </div>
    </section>
  );
};
