interface HomeViewProps {
  language: Language;
  onNavigate: (view: string, projectId?: string) => void;
  onSelectChapter?: (chapter: ChapterFilter) => void;
  onOpenLightbox: (asset: MediaAsset, projectGallery: MediaAsset[]) => void;
  onOpenVideo: (project: PortfolioProject) => void;
}

function getLocalizedTitle(project: PortfolioProject, language: Language): string {
  if (language === 'sv' && project.coverAsset?.titleSv) {
    return project.coverAsset.titleSv;
  }
  return project.title;
}

function getLocalizedSubtitle(project: PortfolioProject, language: Language): string {
  const summary = language === 'sv' ? project.summarySv : project.summaryEn;
  const title = getLocalizedTitle(project, language);
  if (summary && summary.toLowerCase() !== title.toLowerCase()) {
    return summary;
  }
  return project.location;
}

