import React, { useState, useEffect } from 'react';

interface KineticTextProps {
  text: string;
  className?: string;
  as?: 'h1' | 'h2' | 'h3' | 'span' | 'div';
}

export const KineticText: React.FC<KineticTextProps> = ({
  text,
  className = '',
  as: Tag = 'span',
}) => {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState<boolean>(false);

  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return;
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const handler = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, []);

  if (prefersReducedMotion) {
    return <Tag className={className}>{text}</Tag>;
  }

  // Split into words to preserve natural line-wrapping, then split words into characters
  const words = text.split(' ');
  let globalCharIndex = 0;

  return (
    <Tag
      className={`inline-block select-none ${className}`}
      onMouseLeave={() => setHoveredIdx(null)}
    >
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline">
        {words.map((word, wordIdx) => {
          const chars = Array.from(word);
          return (
            <React.Fragment key={wordIdx}>
              <span className="inline-block whitespace-nowrap">
                {chars.map((char) => {
                  const idx = globalCharIndex++;
                  const distance =
                    hoveredIdx !== null ? Math.abs(hoveredIdx - idx) : 99;

                  let transform = 'translate3d(0, 0, 0) scale(1) rotate(0deg)';
                  let colorClass = '';

                  if (distance === 0) {
                    transform = 'translate3d(0, -8px, 0) scale(1.1) rotate(-2deg)';
                    colorClass = 'text-[#f59e0b]';
                  } else if (distance === 1) {
                    const dir = hoveredIdx !== null && idx > hoveredIdx ? 1.5 : -1.5;
                    transform = `translate3d(0, -4px, 0) scale(1.04) rotate(${dir}deg)`;
                  } else if (distance === 2) {
                    transform = 'translate3d(0, -1.5px, 0) scale(1.01)';
                  }

                  return (
                    <span
                      key={idx}
                      onMouseEnter={() => setHoveredIdx(idx)}
                      style={{
                        transform,
                        transition:
                          'transform 0.26s cubic-bezier(0.22, 1, 0.36, 1), color 0.2s ease',
                      }}
                      className={`inline-block cursor-default will-change-transform ${colorClass}`}
                    >
                      {char}
                    </span>
                  );
                })}
              </span>
              {wordIdx < words.length - 1 ? ' ' : null}
            </React.Fragment>
          );
        })}
      </span>
    </Tag>
  );
};
